// hypergraph_test.ts — public/compose/layout/hypergraph.js: determinism, boxes in a
// layer never overlap, boundary and port order are kept, and parity with Chyp's
// own convex_layout on the graphs in parity/composition-views/chyp-layout.json.
//
// Ported from pflow-views-prototype tests/hypergraph.test.mjs (3c47541;
// hypergraph.js is byte-identical in both). The receipt is
// what Chyp's layout does on those graphs, generated by chyp_layout_receipt.py
// (beside the receipt, unmodified from the prototype) from Chyp @3d28483, run
// headless with cvxpy 1.9.3. It lives under parity/, not public/: the site
// does not serve it. The scene-manifest parity (parity/composition-views/
// parity_test.ts) compares ids and never coordinates, so this is the only test
// that holds the layout's geometry.
//
// To regenerate the receipt, run chyp_layout_receipt.py against a Chyp checkout
// at 3d28483 (its docstring has the invocation, with the prototype's paths) and
// write parity/composition-views/chyp-layout.json. A change in the numbers is a
// finding about the layout, never a reason to loosen a tolerance here.
//
// The Chyp cases override the gaps (rowGap 0, wireGap 1, ...) and the relations
// below are measured against DEFAULTS, so neither would notice a default that
// moved. Two tests pin the defaults themselves: DEFAULTS as a literal, and the
// layouts of the composition and the bounded queue's cycle under default options
// against a golden (hypergraph-default-layouts.json, beside the receipt).
import { assert, assertEquals, assertMatch, assertThrows } from "https://deno.land/std@0.224.0/assert/mod.ts";
import { DEFAULTS, feedbackPath, layoutHypergraph as layout, wirePath } from "./hypergraph.js";

// The module is plain JS with JSDoc-free object literals; the tests read its result untyped.
const layoutHypergraph = layout as (graph: any, opts?: any) => any;

const RECEIPT = JSON.parse(await Deno.readTextFile(new URL("../../../parity/composition-views/chyp-layout.json", import.meta.url)));
const EPS = 1e-6;

// The orders/workers/payment links as wires: dequeue fans out to acquire and do:reserve,
// release feeds commit; the queue's items place is exported both ways.
const COMPOSITION = {
    boxes: [
        { id: "orders", inputs: ["orders.in"], outputs: ["dequeue", "orders.out"] },
        { id: "workers", inputs: ["dequeue"], outputs: ["release"] },
        { id: "payment", inputs: ["dequeue", "release"], outputs: ["completed", "rolled_back"] },
    ],
    inputs: ["orders.in"],
    outputs: ["orders.out", "completed", "rolled_back"],
};

// The bounded queue's own cycle: slots -> enqueue -> items -> dequeue -> slots.
const CYCLE = {
    boxes: [
        { id: "enqueue", inputs: ["in", "slots"], outputs: ["items"] },
        { id: "dequeue", inputs: ["items"], outputs: ["out", "slots"] },
    ],
    inputs: ["in"],
    outputs: ["out"],
};

// One box with more ports than boxMinHeight holds, so its height comes from portPitch.
const WIDE = {
    boxes: [{ id: "join", inputs: ["a", "b", "c", "d"], outputs: ["e", "f"] }],
    inputs: ["a", "b", "c", "d"],
    outputs: ["e", "f"],
};

const chypGraphs: Array<[string, any]> = RECEIPT.cases.map((c: any) => [c.name, c.graph]);
const ALL: Array<[string, any]> = [["composition", COMPOSITION], ["cycle", CYCLE], ...chypGraphs];

const boxColumns = (lay: any) => lay.layers.map((ids: string[]) => ids.map((id) => ({ id, ...lay.boxes[id] })));

Deno.test("hypergraph: the receipt is there and covers more than the two hand-written graphs", () => {
    assert(RECEIPT.cases.length >= 4, `${RECEIPT.cases.length} Chyp cases`);
    assertEquals(RECEIPT.chyp.commit.slice(0, 7), "3d28483");
});

Deno.test("hypergraph: deterministic, same input, same output, every time", () => {
    for (const [name, g] of ALL) {
        const a = layoutHypergraph(g);
        const b = layoutHypergraph(structuredClone(g));
        const c = layoutHypergraph(JSON.parse(JSON.stringify(g)));
        assertEquals(a, b, name);
        assertEquals(JSON.stringify(a), JSON.stringify(c), name);
    }
});

Deno.test("hypergraph: boxes in one layer never overlap and keep rowGap between them", () => {
    for (const [name, g] of ALL) {
        const lay = layoutHypergraph(g);
        for (const col of boxColumns(lay)) {
            const byY = [...col].sort((p: any, q: any) => p.y - q.y);
            for (let i = 1; i < byY.length; i++) {
                const gap = (byY[i].y - byY[i].h / 2) - (byY[i - 1].y + byY[i - 1].h / 2);
                assert(gap >= DEFAULTS.rowGap - EPS, `${name}: ${byY[i - 1].id} / ${byY[i].id} gap ${gap}`);
            }
            // the reported order is the top-to-bottom order
            assertEquals(col.map((b: any) => b.id), byY.map((b: any) => b.id), name);
        }
    }
});

Deno.test("hypergraph: no wire runs through a box", () => {
    for (const [name, g] of ALL) {
        const lay = layoutHypergraph(g);
        const all: Array<[string, any]> = Object.entries(lay.boxes);
        for (const [vid, v] of Object.entries<any>(lay.vertices)) {
            for (const path of v.paths) {
                for (const p of path) {
                    for (const [bid, b] of all) {
                        if (p.x > b.inX + EPS && p.x < b.outX - EPS) {
                            assert(Math.abs(p.y - b.y) >= b.h / 2 - EPS, `${name}: wire ${vid} at (${p.x}, ${p.y}) inside box ${bid}`);
                        }
                    }
                }
            }
        }
    }
});

Deno.test("hypergraph: order is kept, boundary order, port order, wire ends on their ports", () => {
    for (const [name, g] of ALL) {
        const lay = layoutHypergraph(g);
        const inc = (ys: number[], what: string) => {
            for (let i = 1; i < ys.length; i++) assert(ys[i] - ys[i - 1] >= DEFAULTS.wireGap - EPS, `${name}: ${what} ${ys}`);
        };
        inc(lay.inputs.map((p: any) => p.y), "inputs");
        inc(lay.outputs.map((p: any) => p.y), "outputs");
        assertEquals(lay.inputs.map((p: any) => p.vertex), g.inputs, name);
        assertEquals(lay.outputs.map((p: any) => p.vertex), g.outputs, name);
        for (const b of g.boxes) {
            const L = lay.boxes[b.id];
            assertEquals(L.inY.length, b.inputs.length, name);
            assertEquals(L.outY.length, b.outputs.length, name);
            for (let i = 1; i < L.inY.length; i++) assert(L.inY[i] > L.inY[i - 1], `${name}: ${b.id} inY`);
            for (let i = 1; i < L.outY.length; i++) assert(L.outY[i] > L.outY[i - 1], `${name}: ${b.id} outY`);
            // each forward wire end lands exactly on the port it belongs to
            b.inputs.forEach((v: string, k: number) => {
                const V = lay.vertices[v];
                const hit = [...V.paths.map((p: any) => p[p.length - 1]), ...V.feedback.map((p: any) => p[p.length - 1])]
                    .some((q: any) => Math.abs(q.x - L.inX) < EPS && Math.abs(q.y - L.inY[k]) < EPS);
                assert(hit, `${name}: ${v} does not reach ${b.id}.in[${k}]`);
            });
            b.outputs.forEach((v: string, k: number) => {
                const hit = lay.vertices[v].paths.some((p: any) => Math.abs(p[0].x - L.outX) < EPS && Math.abs(p[0].y - L.outY[k]) < EPS);
                assert(hit, `${name}: ${v} does not leave ${b.id}.out[${k}]`);
            });
        }
        // inputs on the left edge, outputs on the right, boxes between
        for (const p of lay.inputs) assert(p.x <= Math.min(...Object.values<any>(lay.boxes).map((b) => b.inX), Infinity), name);
        for (const p of lay.outputs) assert(p.x >= Math.max(...Object.values<any>(lay.boxes).map((b) => b.outX), -Infinity), name);
        // every path runs left to right
        for (const v of Object.values<any>(lay.vertices)) {
            for (const path of v.paths) for (let i = 1; i < path.length; i++) assert(path[i].x >= path[i - 1].x - EPS, name);
        }
    }
});

Deno.test("hypergraph: layers, a box sits right of every box that feeds it (cycles excepted)", () => {
    const lay = layoutHypergraph(COMPOSITION);
    assertEquals(lay.layers, [["orders"], ["workers"], ["payment"]]);
    assertEquals(lay.vertices.dequeue.paths.length, 3, "one producer end, two consumer ends");
    assertEquals(lay.vertices.dequeue.route, null, "a fan-out has no single route");
    assert(lay.vertices.release.route.length >= 3);
});

Deno.test("hypergraph: cycles are broken, not refused, the back edge becomes a feedback route", () => {
    const lay = layoutHypergraph(CYCLE);
    assertEquals(lay.layers, [["enqueue"], ["dequeue"]]);
    assertEquals(lay.stats.feedbackEdges, 1);
    assertEquals(lay.vertices.slots.feedback.length, 1);
    const fb = lay.vertices.slots.feedback[0];
    assert(fb[1].y > Math.max(...Object.values<any>(lay.boxes).map((b) => b.y + b.h / 2)), "routed below the boxes");
    assert(lay.height >= fb[1].y);
    assertMatch(feedbackPath(fb), /^M[\d.]+ [\d.]+( L[\d.]+ [\d.]+){4}$/);
});

Deno.test("hypergraph: edge cases, empty graph, a bare identity wire, a duplicate box id", () => {
    const empty = layoutHypergraph({ boxes: [], inputs: [], outputs: [] });
    assertEquals(empty.boxes, {});
    const id = layoutHypergraph({ boxes: [], inputs: ["a"], outputs: ["a"] });
    const r = id.vertices.a.route;
    assertEquals(r[0].y, r[r.length - 1].y, "identity is a straight wire");
    assertEquals(id.stats.bend, 0);
    assertThrows(
        () => layoutHypergraph({ boxes: [{ id: "x", inputs: [], outputs: [] }, { id: "x", inputs: [], outputs: [] }], inputs: [], outputs: [] }),
        Error,
        "duplicate box id",
    );
});

// --- the defaults, pinned -------------------------------------------------------------

Deno.test("hypergraph: DEFAULTS are these numbers (the relations above are measured against them)", () => {
    // A default that moves changes every caller that does not pass its own: the geometry (box and wire gaps,
    // port pitch, margins, the feedback lanes) and the solver (tolerance, sweeps, objective). Change one on
    // purpose, change this and regenerate the golden below in the same commit.
    assertEquals({ ...DEFAULTS }, {
        boxWidth: 64,
        boxMinHeight: 32,
        portPitch: 16,
        rowGap: 16,
        wireGap: 16,
        gap: 48,
        margin: 24,
        feedbackGap: 16,
        objective: "l1",
        compact: 0.1,
        portOffsets: null,
        layerOrder: null,
        orderSweeps: 4,
        maxSweeps: 3000,
        tol: 1e-6,
    });
    assert(Object.isFrozen(DEFAULTS));
});

// The module's whole result for the three hand-written graphs, with no options, as hypergraph-default-layouts.json
// holds it. That is the layout a caller gets when it passes nothing: the Laws view passes its own proportions
// for the box, port, gap and margin keys (laws.js fromSpec) and inherits the rest from DEFAULTS (feedbackGap, tol,
// compact, objective, the sweeps), so a drift in either shows up in the Laws view's diagrams too.
//
// Regenerate (after a deliberate change to hypergraph.js or DEFAULTS; the diff is the review) from the repo root:
//
//   node --input-type=module -e "import fs from 'node:fs'; import { layoutHypergraph } from './public/compose/layout/hypergraph.js';
//     const f = 'parity/composition-views/hypergraph-default-layouts.json'; const g = JSON.parse(fs.readFileSync(f, 'utf8'));
//     for (const c of g.cases) c.layout = layoutHypergraph(c.graph); fs.writeFileSync(f, JSON.stringify(g, null, 2) + '\n');"
//
// (the graphs are stored in the golden and checked here against COMPOSITION, CYCLE and WIDE, so they are not retyped).
const GOLDEN = JSON.parse(await Deno.readTextFile(new URL("../../../parity/composition-views/hypergraph-default-layouts.json", import.meta.url)));

/** Deep equality, numbers to within one rounding step: the layout rounds every coordinate to 1e-6. */
function assertNear(actual: any, expected: any, path: string) {
    if (typeof expected === "number") {
        assert(typeof actual === "number" && Math.abs(actual - expected) <= 1.5e-6, `${path}: ${actual}, golden ${expected}`);
    } else if (Array.isArray(expected)) {
        assert(Array.isArray(actual) && actual.length === expected.length, `${path}: ${JSON.stringify(actual)?.slice(0, 80)} is not the golden's ${expected.length} items`);
        expected.forEach((e, i) => assertNear(actual[i], e, `${path}[${i}]`));
    } else if (expected && typeof expected === "object") {
        assert(actual && typeof actual === "object", `${path}: not an object`);
        assertEquals(Object.keys(actual).sort(), Object.keys(expected).sort(), `${path}: keys`);
        for (const k of Object.keys(expected)) assertNear(actual[k], expected[k], `${path}.${k}`);
    } else {
        assertEquals(actual, expected, path);
    }
}

Deno.test("hypergraph: the composition, the cycle and a wide box laid out with default options are the golden's geometry", () => {
    assertEquals(GOLDEN.cases.map((c: any) => c.name), ["composition", "cycle", "wide"]);
    for (const [i, g] of [COMPOSITION, CYCLE, WIDE].entries()) assertEquals(GOLDEN.cases[i].graph, g, "the golden was made from another graph");
    for (const c of GOLDEN.cases) {
        const lay = layoutHypergraph(c.graph);
        // every coordinate: boxes, ports, wire paths, feedback lanes, the extent and the solver's own counts
        assertNear(lay, c.layout, c.name);
    }
});

Deno.test("hypergraph: wirePath, level runs are lines, steps are cubics with horizontal tangents", () => {
    assertEquals(wirePath([{ x: 0, y: 5 }, { x: 10, y: 5 }]), "M0 5 L10 5");
    assertEquals(wirePath([{ x: 0, y: 0 }, { x: 10, y: 20 }]), "M0 0 C4 0 6 20 10 20");
});

// --- parity with Chyp ----------------------------------------------------------------

// Chyp's geometry in its own units (layout.py:82-111, graphscene.py:152-165): boundary
// vertices >= 1 apart, boxes >= (s1+s2)/2 apart with box_size s in {1, 2}, ports at
// i/(n-1) - 0.5, L1 objective with 0.1 x spread.
const CHYP_OPTS = { rowGap: 0, wireGap: 1, margin: 0, gap: 1.9, boxWidth: 1.1, portOffsets: (i: number, n: number) => (n <= 1 ? 0 : i / (n - 1) - 0.5) };
const sized = (g: any) => ({ ...g, boxes: g.boxes.map((b: any) => ({ ...b, height: b.box_size })) });

/** convex_layout's objective (layout.py:82-117) evaluated on any layout of a monogamous graph. */
function chypObjective(graph: any, lay: any, layers: string[][]) {
    let f = 0;
    const spread = (ys: number[]) => { for (let i = 1; i < ys.length; i++) f += 0.1 * Math.abs(ys[i] - ys[i - 1]); };
    spread(lay.inputs.map((p: any) => p.y));
    spread(lay.outputs.map((p: any) => p.y));
    for (const l of layers) spread(l.map((id) => lay.boxes[id].y));
    const from: Record<string, number> = {}, to: Record<string, number> = {};
    graph.inputs.forEach((v: string, i: number) => { from[v] ??= lay.inputs[i].y; });
    graph.outputs.forEach((v: string, j: number) => { to[v] ??= lay.outputs[j].y; });
    for (const b of graph.boxes) {
        b.outputs.forEach((v: string, k: number) => { from[v] ??= lay.boxes[b.id].outY[k]; });
        b.inputs.forEach((v: string, k: number) => { to[v] ??= lay.boxes[b.id].inY[k]; });
    }
    for (const v of Object.keys(from)) if (v in to) f += Math.abs(from[v] - to[v]);
    return f;
}

Deno.test("hypergraph: Chyp parity, the receipt is Chyp's own optimum (recomputed objective = problem.value)", () => {
    for (const c of RECEIPT.cases) assert(Math.abs(c.objective - c.objective_recomputed) < 1e-6, c.name);
});

Deno.test("hypergraph: Chyp parity, same layers as layer_decomp for every real box", () => {
    for (const c of RECEIPT.cases) {
        const chypLayer: Record<string, number> = {};
        c.layers.forEach((l: string[], i: number) => l.forEach((id) => { chypLayer[id] = i + 1; }));
        const lay = layoutHypergraph(sized(c.graph), CHYP_OPTS);
        for (const b of c.graph.boxes) assertEquals(lay.boxes[b.id].layer, chypLayer[b.id], `${c.name}: ${b.id}`);
    }
});

Deno.test("hypergraph: Chyp parity, given Chyp's layers and order the solver reaches cvxpy's optimum", () => {
    for (const c of RECEIPT.cases) {
        const g = sized(c.expanded); // Chyp's graph after layer_decomp, identity boxes included
        const lay = layoutHypergraph(g, { ...CHYP_OPTS, layerOrder: c.layers });
        assertEquals(lay.layers, c.layers, c.name);
        const ours = chypObjective(g, lay, c.layers);
        const row = `${c.name}: chyp ${c.objective.toFixed(4)} ours ${ours.toFixed(4)}`;
        assert(ours >= c.objective - 1e-4, `below Chyp's optimum? ${row}`);
        assert(ours <= c.objective * 1.005 + 1e-6, row);
        assert(Math.abs(lay.stats.objective - ours) < 1e-3, `${c.name}: internal objective is Chyp's objective (${lay.stats.objective} vs ${ours})`);
    }
});

/** Crossings in Chyp's own drawing: wires between the same two adjacent slots whose order flips. */
function chypCrossings(c: any) {
    const g = c.expanded, pos = c.layout;
    const layerOf: Record<string, number> = {};
    c.layers.forEach((l: string[], i: number) => l.forEach((id) => { layerOf[id] = i + 1; }));
    const ends: Record<string, any> = {};
    const at = (v: string) => (ends[v] ??= {});
    const shift = (i: number, n: number) => (n <= 1 ? 0 : i / (n - 1) - 0.5); // graphscene.py:152-165
    g.inputs.forEach((v: string) => Object.assign(at(v), { pl: 0, py: pos.vertices[v].y }));
    g.outputs.forEach((v: string) => Object.assign(at(v), { cl: c.layers.length + 1, cy: pos.vertices[v].y }));
    for (const b of g.boxes) {
        b.outputs.forEach((v: string, i: number) => Object.assign(at(v), { pl: layerOf[b.id], py: pos.edges[b.id].y + shift(i, b.outputs.length) }));
        b.inputs.forEach((v: string, i: number) => Object.assign(at(v), { cl: layerOf[b.id], cy: pos.edges[b.id].y + shift(i, b.inputs.length) }));
    }
    const ws = Object.values(ends).filter((e) => e.pl !== undefined && e.cl !== undefined);
    let x = 0;
    for (let i = 0; i < ws.length; i++) {
        for (let j = i + 1; j < ws.length; j++) {
            if (ws[i].pl === ws[j].pl && ws[i].cl === ws[j].cl && (ws[i].py - ws[j].py) * (ws[i].cy - ws[j].cy) < -1e-9) x++;
        }
    }
    return x;
}

Deno.test("hypergraph: Chyp parity, our own ordering crosses no more wires than Chyp's drawing", () => {
    for (const c of RECEIPT.cases) {
        const ours = layoutHypergraph(c.graph).stats.crossings;
        const theirs = chypCrossings(c);
        assert(ours <= theirs, `${c.name}: chyp ${theirs} ours ${ours}`);
    }
});

Deno.test("hypergraph: rewrite receipt, Chyp marks the assoc step VALID, the bialg step INVALID, and leaves no highlight", () => {
    const steps = Object.fromEntries(RECEIPT.rewrite.steps.map((s: any) => [s.name, s]));
    assertEquals(steps.ba1.status, "VALID");
    assertEquals(steps.wrong.status, "INVALID");
    assertEquals(steps.ba1.highlight_flags_after_check, []);
    const m = RECEIPT.rewrite.matches[0];
    assertEquals(m.equals_stated_rhs, true);
    // the matched part and the inserted part are layout-able with ids the views can highlight
    const before = layoutHypergraph(m.lhs_graph), after = layoutHypergraph(m.rewritten_graph);
    for (const e of m.lhs_matched_edges) assert(before.boxes[e], e);
    for (const e of m.rhs_inserted_edges) assert(after.boxes[e], e);
});
